// Lấy thông tin tin nhắn từ khách hàng
const inData = $('Nhận Tin Từ Tikovia CRM').first().json.body || {};
const userMsg = String(inData.message || '').toLowerCase().trim();
const cleanUserMsg = " " + userMsg.replace(/[,.?!:;()]/g, ' ') + " ";
const senderName = inData.sender_name || 'bạn';

// Lấy toàn bộ danh sách kịch bản từ Google Sheet
const scenarios = $input.all().map(i => i.json);

let matchedScenario = null;
let defaultScenario = null;

for (const sc of scenarios) {
  const status = String(sc.Trang_Thai || sc.Status || '').trim().toLowerCase();
  // Chỉ xét các kịch bản đang Bật
  if (status !== 'bật' && status !== 'bat' && status !== 'active' && status !== 'on') {
    continue;
  }

  const topic = String(sc.Chu_De || '').trim().toLowerCase();
  if (topic === 'mac_dinh' || topic === 'mặc định' || topic === 'fallback') {
    defaultScenario = sc;
  }

  const rawKeywords = String(sc.Tu_Khoa || sc.Keywords || '');
  const keywords = rawKeywords.split('|').map(k => k.trim().toLowerCase()).filter(Boolean);

  for (const kw of keywords) {
    if (kw === '*') continue;
    // Khớp từ nguyên vẹn hoặc cụm từ để tránh dính từ con (vd: 'hi' dính vào 'chi phí')
    const cleanKw = " " + kw + " ";
    if (cleanUserMsg.includes(cleanKw) || userMsg === kw) {
      matchedScenario = sc;
      break;
    }
  }

  if (matchedScenario) break;
}

// Nếu không khớp từ khóa nào, dùng kịch bản Mặc định
const finalSc = matchedScenario || defaultScenario;

let replyText = '';
let replyImage = '';

if (finalSc) {
  replyText = String(finalSc.Cau_Tra_Loi || finalSc.Answer || '').replace(/{ten_khach}/g, senderName);
  let rawImg = String(finalSc.Link_Anh || finalSc.Image_URL || '').trim();
  if (rawImg.startsWith('http://') || rawImg.startsWith('https://')) {
    replyImage = rawImg;
  }
} else {
  replyText = `Dạ chào ${senderName}! Cảm ơn bạn đã nhắn tin cho Tikovia. Câu hỏi của bạn đã được ghi nhận và chuyên viên tư vấn sẽ phản hồi bạn trong ít phút nhé! (Hotline: 0702 536 927)`;
}

return {
  json: {
    company_id: inData.company_id,
    channel_id: inData.channel_id,
    sender_id: inData.sender_id,
    source: 'zalo',
    reply_text: replyText,
    reply_image: replyImage,
    matched_topic: finalSc?.Chu_De || 'Không khớp (Fallback)'
  }
};
